				$E3, $82, $22, $F6, $FF, $E5, $19, $47, $8F, $C8, $A2, $23, $E1, $37, $F8, $8C, $F1, $8C, $A3, $E3, $FD, $8C, $40
				SPR_USE_PREdef0     // Create 3 directions

